#!/usr/bin/env node
/* Assemble state_pesticide_laws.js from laws/*.json.
 *
 * Legal edits belong in one state's JSON file. This script is the only
 * step that refreshes the runtime matrix the app already loads. It does
 * not change completeness rules, log fields, or badges.
 *
 *   node tools/bundle-state-laws.js              write runtime file + SW edition
 *   node tools/bundle-state-laws.js --check      exit 1 if generated file is stale
 *   node tools/bundle-state-laws.js --stamp KS   set KS reviewedAt + edition to today
 *   node tools/bundle-state-laws.js --init-from-js
 *        one-shot: split the current JS matrix into laws/*.json
 */
'use strict';

const fs = require('fs');
const path = require('path');
const vm = require('vm');

const root = path.join(__dirname, '..');
const lawsDir = path.join(root, 'laws');
const runtimePath = path.join(root, 'state_pesticide_laws.js');
const swPath = path.join(root, 'sw.js');
const metaPath = path.join(lawsDir, '_meta.json');
const baseFieldsPath = path.join(lawsDir, '_base_fields.json');

const US_STATES = [
  'AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA','ME','MD',
  'MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR','PA','RI','SC',
  'SD','TN','TX','UT','VT','VA','WA','WV','WI','WY'
];

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

function todayIso() {
  const d = new Date();
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

function readJson(p) {
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

function writeJson(p, obj) {
  fs.writeFileSync(p, JSON.stringify(obj, null, 2) + '\n');
}

function loadMeta() {
  const meta = readJson(metaPath);
  if (!ISO_DATE.test(meta.researchDate)) {
    throw new Error('laws/_meta.json researchDate must be YYYY-MM-DD');
  }
  const staleDays = Number(meta.staleDays);
  if (!Number.isFinite(staleDays) || staleDays < 1) {
    throw new Error('laws/_meta.json staleDays must be a positive number');
  }
  return { researchDate: meta.researchDate, staleDays: staleDays };
}

function loadBaseFields() {
  const fields = readJson(baseFieldsPath);
  if (!Array.isArray(fields) || fields.length < 10) {
    throw new Error('laws/_base_fields.json must be an array of field names');
  }
  return fields;
}

function loadStateFile(code) {
  const p = path.join(lawsDir, code + '.json');
  if (!fs.existsSync(p)) throw new Error('missing ' + p);
  const row = readJson(p);
  if (row.code !== code) throw new Error(code + '.json code mismatch: ' + row.code);
  if (!ISO_DATE.test(row.reviewedAt)) {
    throw new Error(code + '.json reviewedAt must be YYYY-MM-DD');
  }
  const law = Object.assign({}, row);
  delete law.code;
  return law;
}

function loadAllStates() {
  const extra = fs.readdirSync(lawsDir).filter((f) => {
    if (!/^[A-Z]{2}\.json$/.test(f)) return false;
    return US_STATES.indexOf(f.slice(0, 2)) < 0;
  });
  if (extra.length) throw new Error('unexpected state files: ' + extra.join(', '));
  const out = {};
  US_STATES.forEach((code) => { out[code] = loadStateFile(code); });
  return out;
}

function generatedSource(meta, states, baseFields) {
  const lawsJson = JSON.stringify(states, null, 2);
  const baseJson = JSON.stringify(baseFields, null, 2);
  return `/* AUTO-GENERATED by tools/bundle-state-laws.js — do not edit by hand.
 *
 * To change one state's recordkeeping rule, edit laws/XX.json and run:
 *   node tools/bundle-state-laws.js
 * Optional: node tools/bundle-state-laws.js --stamp XX  (sets reviewedAt + edition to today)
 *
 * Built for post-July 11, 2025 reality: USDA 7 CFR Part 110 (federal private
 * applicator RUP recordkeeping) was rescinded. State pesticide acts, WPS,
 * and product labels control.
 *
 * Scope: agricultural application RECORDKEEPING field coverage for each
 * state's researched requirements. This is not a substitute for:
 *   - Worker Protection Standard (40 CFR Part 170) employer duties
 *   - California PUR / CalAgPermits electronic reporting
 *   - New York Pesticide Reporting Law electronic filings
 *   - Product-label-specific record mandates (dicamba, fumigants, etc.)
 *
 * verification values:
 *   researched — fields sourced from state rule/statute/agency guidance
 *   partial    — core fields verified; some private/commercial nuances open
 *   uncertain  — limited authoritative field list; capture recommended base
 *
 * privateDuty:
 *   required  — private applicators have a researched state recordkeeping duty
 *   none      — state sources indicate no private applicator record duty
 *   uncertain — private-applicator duty not verified after Part 110 rescission
 *
 * customerCopyDays:
 *   number — researched commercial customer-copy window (days)
 *   null   — no researched customer-copy duty encoded (do not invent one)
 *
 * recordDeadline:
 *   { count, unit: 'hours'|'calendarDays'|'businessDays'|'sameDay' }
 *   Business days are Mon–Fri only (no holiday calendar). Confirm with agency.
 *   recordWithinHours is retained as a coarse fallback / display hint.
 *
 * reviewedAt is when this state's citation was last opened. It is not a
 * completeness field and must not change badges by itself.
 *
 * Matrix edition: ${meta.researchDate}. Always confirm with your state agency.
 */
const STATE_LAWS_RESEARCH_DATE = ${JSON.stringify(meta.researchDate)};
const STATE_LAW_STALE_DAYS = ${JSON.stringify(meta.staleDays)};

function stateLawParseIsoDate(iso) {
  if (typeof iso !== 'string' || !/^\\d{4}-\\d{2}-\\d{2}$/.test(iso)) return NaN;
  return Date.parse(iso + 'T00:00:00Z');
}

function stateLawIsStale(law, now) {
  const t = stateLawParseIsoDate(law && law.reviewedAt);
  if (!Number.isFinite(t)) return true;
  const n = now instanceof Date ? now.getTime() : Number(now);
  if (!Number.isFinite(n)) return true;
  return (n - t) > STATE_LAW_STALE_DAYS * 86400000;
}

const STATE_LAWS = ${lawsJson};

// Recommended base record for every application (drift defense / audits / WPS overlap).
const BASE_RECORD_FIELDS = ${baseJson};
`;
}

function patchSwEdition(researchDate) {
  const sw = fs.readFileSync(swPath, 'utf8');
  if (!/const LAWS_EDITION = '[0-9]{4}-[0-9]{2}-[0-9]{2}';/.test(sw)) {
    throw new Error('sw.js is missing const LAWS_EDITION = \'YYYY-MM-DD\';');
  }
  const next = sw.replace(
    /const LAWS_EDITION = '[0-9]{4}-[0-9]{2}-[0-9]{2}';/,
    "const LAWS_EDITION = '" + researchDate + "';"
  );
  if (next !== sw) fs.writeFileSync(swPath, next);
}

function writeRuntime(meta, states, baseFields) {
  const src = generatedSource(meta, states, baseFields);
  fs.writeFileSync(runtimePath, src);
  patchSwEdition(meta.researchDate);
  return src;
}

function initFromJs() {
  const lawsCode = fs.readFileSync(runtimePath, 'utf8');
  const ctx = {};
  vm.runInNewContext(
    lawsCode + '\nthis.STATE_LAWS = STATE_LAWS; this.BASE_RECORD_FIELDS = BASE_RECORD_FIELDS;',
    ctx
  );
  const dateMatch = lawsCode.match(/Source research date: (\d{4}-\d{2}-\d{2})/);
  const researchDate = (dateMatch && dateMatch[1]) || '2026-07-31';
  if (!fs.existsSync(lawsDir)) fs.mkdirSync(lawsDir);
  writeJson(metaPath, { researchDate: researchDate, staleDays: 365 });
  writeJson(baseFieldsPath, ctx.BASE_RECORD_FIELDS);
  Object.keys(ctx.STATE_LAWS).sort().forEach((code) => {
    const law = ctx.STATE_LAWS[code];
    const row = Object.assign({ code: code, reviewedAt: law.reviewedAt || researchDate }, law);
    writeJson(path.join(lawsDir, code + '.json'), row);
  });
}

function stamp(code) {
  const upper = String(code || '').toUpperCase();
  if (US_STATES.indexOf(upper) < 0) throw new Error('unknown state ' + code);
  const iso = todayIso();
  const p = path.join(lawsDir, upper + '.json');
  const row = readJson(p);
  row.reviewedAt = iso;
  writeJson(p, row);
  const meta = readJson(metaPath);
  meta.researchDate = iso;
  writeJson(metaPath, meta);
  return upper;
}

function main(argv) {
  const args = argv.slice(2);
  if (args[0] === '--init-from-js') {
    initFromJs();
    const meta = loadMeta();
    const states = loadAllStates();
    const base = loadBaseFields();
    writeRuntime(meta, states, base);
    console.log('Wrote laws/*.json from state_pesticide_laws.js and rebundled.');
    return;
  }
  if (args[0] === '--stamp') {
    const code = stamp(args[1]);
    const meta = loadMeta();
    writeRuntime(meta, loadAllStates(), loadBaseFields());
    console.log('Stamped', code, 'and edition', meta.researchDate);
    return;
  }
  const meta = loadMeta();
  const states = loadAllStates();
  const base = loadBaseFields();
  const src = generatedSource(meta, states, base);
  if (args[0] === '--check') {
    const current = fs.readFileSync(runtimePath, 'utf8');
    if (current !== src) {
      console.error('state_pesticide_laws.js is stale. Run: node tools/bundle-state-laws.js');
      process.exit(1);
    }
    const sw = fs.readFileSync(swPath, 'utf8');
    if (!sw.includes("const LAWS_EDITION = '" + meta.researchDate + "';")) {
      console.error('sw.js LAWS_EDITION does not match laws/_meta.json researchDate');
      process.exit(1);
    }
    console.log('ok  - state laws bundle is current');
    return;
  }
  writeRuntime(meta, states, base);
  console.log('Wrote state_pesticide_laws.js (' + Object.keys(states).length + ' states, edition ' + meta.researchDate + ')');
}

if (require.main === module) {
  try {
    main(process.argv);
  } catch (e) {
    console.error(e.message || e);
    process.exit(1);
  }
}

module.exports = {
  US_STATES, loadMeta, loadAllStates, loadBaseFields, generatedSource, todayIso
};
